using InventoryWarehouseApi.Application.LowStock;using Microsoft.Extensions.Options;
namespace InventoryWarehouseApi.Api.BackgroundJobs;
public sealed class LowStockMonitoringWorker(IServiceScopeFactory scopes,IOptions<LowStockMonitoringOptions> options,ILogger<LowStockMonitoringWorker> logger):BackgroundService
{
 protected override async Task ExecuteAsync(CancellationToken stoppingToken){var o=options.Value;if(!o.Enabled){logger.LogInformation("Low-stock monitoring worker disabled by configuration");return;}logger.LogInformation("Low-stock monitoring worker started");while(!stoppingToken.IsCancellationRequested){try{await using var scope=scopes.CreateAsyncScope();var result=await scope.ServiceProvider.GetRequiredService<ILowStockMonitoringService>().RunAsync(DateTimeOffset.UtcNow,stoppingToken);logger.LogInformation("Low-stock scan evaluated {EvaluatedThresholdCount}; low {LowStockCount}; triggered {TriggeredAlertCount}; updated {UpdatedActiveAlertCount}; resolved {ResolvedAlertCount}",result.EvaluatedThresholdCount,result.LowStockCount,result.TriggeredAlertCount,result.UpdatedActiveAlertCount,result.ResolvedAlertCount);}catch(OperationCanceledException) when(stoppingToken.IsCancellationRequested){break;}catch(Exception ex){logger.LogError(ex,"Low-stock monitoring scan failed");}try{await Task.Delay(TimeSpan.FromSeconds(o.IntervalSeconds),stoppingToken);}catch(OperationCanceledException) when(stoppingToken.IsCancellationRequested){break;}}logger.LogInformation("Low-stock monitoring worker stopped");}
}
